window.__reformedWorks["schaff_creeds3_01"] = {"id":"schaff_creeds3_01","a":"Schaff, Philip","t":"Luther's Small Catechism. A.D. 1529.","u":"https://ccel.org/ccel/schaff/creeds3","c":[{"t":"Luther's Small Catechism. A.D. 1529.","s":[{"t":"","p":["[The German text is taken from the third edition, which appeared in Wittenberg, 1531, and was accurately republished by Dr. Schneider, Berlin, 1853. The orthography is modernized, and some words (as Erstes Haupstück, Gebot) are inserted in parentheses from the later edition. The English translation is more literal than those in use among the Lutheran churches in America. On Luther's Catechisms, see Vol. I. § 43, pp. 245 sqq.]"]}]}]};
